CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 REAL DEFAULT 'd', c1 VARCHAR(10) COLLATE NOCASE, c2 NUMERIC NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES(x'2e6e632b', x'b0', -1);
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES(NULL, NULL, x'fee46a824b');
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES(0, NULL, 3);
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES(NULL, 4.5e-310, 4);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 NUMERIC COLLATE NOCASE, c1 INT, c2 INT CHECK(c2 IS NULL OR length(c2) < 40), ref INTEGER REFERENCES t0(id));
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 ANY CHECK(c0 IS NULL OR length(c0) < 40), c1 INTEGER COLLATE NOCASE, c2 TEXT DEFAULT 'd', c3 TEXT, c4 TEXT DEFAULT 'd', ref INTEGER REFERENCES t1(id)) STRICT;
INSERT OR IGNORE INTO t2(c0, c1, c2, c3, c4, ref) VALUES('señor', 480, 'rho', 'x_y', 'a%b', 6);
SELECT length('NULL'), upper('NULL'), lower('NULL'), substr('NULL', -3, 0), instr('NULL', 'chi'), replace('NULL', 'a', '_'), trim('NULL'), ltrim('NULL', 'ab'), hex('NULL'), quote('NULL'), unicode('NULL'), 'NULL' LIKE '_', 'NULL' GLOB '*[a-m]*', char(68, 411), 'NULL' || 'chi', 'NULL' < 'chi', 'NULL' = 'chi' COLLATE NOCASE;
SELECT length('42'), upper('42'), lower('42'), substr('42', 4, 4), instr('42', 'sigma'), replace('42', 'a', ''), trim('42'), ltrim('42', 'ab'), hex('42'), quote('42'), unicode('42'), '42' LIKE 'A%', '42' GLOB '?', char(74, 686), '42' || 'sigma', '42' < 'sigma', '42' = 'sigma' COLLATE NOCASE;
SELECT length('alpha'), upper('alpha'), lower('alpha'), substr('alpha', -2, 3), instr('alpha', 'Ελλάδα'), replace('alpha', '', ''), trim('alpha'), ltrim('alpha', 'ab'), hex('alpha'), quote('alpha'), unicode('alpha'), 'alpha' LIKE '%é%', 'alpha' GLOB 'a*', char(77, 518), 'alpha' || 'Ελλάδα', 'alpha' < 'Ελλάδα', 'alpha' = 'Ελλάδα' COLLATE NOCASE;
SELECT length('MU'), upper('MU'), lower('MU'), substr('MU', -3, 3), instr('MU', 'epsilon'), replace('MU', '', ''), trim('MU'), ltrim('MU', 'ab'), hex('MU'), quote('MU'), unicode('MU'), 'MU' LIKE '%a_', 'MU' GLOB '*', char(82, 661), 'MU' || 'epsilon', 'MU' < 'epsilon', 'MU' = 'epsilon' COLLATE NOCASE;
SELECT length('chi'), upper('chi'), lower('chi'), substr('chi', 1, 2), instr('chi', 'alpha'), replace('chi', 'a', ''), trim('chi'), ltrim('chi', 'ab'), hex('chi'), quote('chi'), unicode('chi'), 'chi' LIKE '%é%', 'chi' GLOB '*[a-m]*', char(88, 786), 'chi' || 'alpha', 'chi' < 'alpha', 'chi' = 'alpha' COLLATE NOCASE;
SELECT length('omega'), upper('omega'), lower('omega'), substr('omega', -3, 3), instr('omega', ' pad '), replace('omega', 'a', '_'), trim('omega'), ltrim('omega', 'ab'), hex('omega'), quote('omega'), unicode('omega'), 'omega' LIKE '%é%', 'omega' GLOB 'a*', char(78, 963), 'omega' || ' pad ', 'omega' < ' pad ', 'omega' = ' pad ' COLLATE NOCASE;
UPDATE t0 SET c0 = (c2 >> nullif(c0, c1));
DELETE FROM t0 WHERE id % 4 = 1;
SELECT * FROM t0 ORDER BY id, c0, c1, c2;
SELECT length('nu'), upper('nu'), lower('nu'), substr('nu', 2, 5), instr('nu', 'sigma'), replace('nu', 'é', 'XY'), trim('nu'), ltrim('nu', 'ab'), hex('nu'), quote('nu'), unicode('nu'), 'nu' LIKE 'a%', 'nu' GLOB '?', char(86, 690), 'nu' || 'sigma', 'nu' < 'sigma', 'nu' = 'sigma' COLLATE NOCASE;
